# -*- coding: utf-8 -*-
"""元素周期表数据（118 个元素）。

每个元素包含：
  - 基本参数：原子序数、符号、中英文名、相对原子质量、族/周期/区块、电负性、电子排布、常温状态
  - 发现信息：年代、发现者、较详细的发现过程
  - 丰度：地壳丰度（ppm，质量分数）、宇宙丰度（以 Si=10⁶ 为基准的原子数比）
  - 应用信息：在自然界的主要存在形式、主要化合物、在生产中的用途
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional

# ---------------------------------------------------------------- 元素分类
CAT_ALKALI = "alkali"              # 碱金属（第 1 族，不含氢）
CAT_ALKALINE = "alkaline"          # 碱土金属（第 2 族）
CAT_TRANSITION = "transition"      # 过渡金属
CAT_POST = "post"                  # 主族金属（贫金属）
CAT_METALLOID = "metalloid"        # 类金属（半金属）
CAT_NONMETAL = "nonmetal"          # 非金属
CAT_HALOGEN = "halogen"            # 卤素（第 17 族）
CAT_NOBLE = "noble"                # 稀有气体（第 18 族）
CAT_LANTHANIDE = "lanthanide"      # 镧系
CAT_ACTINIDE = "actinide"          # 锕系
CAT_UNKNOWN = "unknown"            # 性质尚不明确（超重元素）

CATEGORY_NAMES = {
    CAT_ALKALI: "碱金属",
    CAT_ALKALINE: "碱土金属",
    CAT_TRANSITION: "过渡金属",
    CAT_POST: "主族金属",
    CAT_METALLOID: "类金属",
    CAT_NONMETAL: "非金属",
    CAT_HALOGEN: "卤素",
    CAT_NOBLE: "稀有气体",
    CAT_LANTHANIDE: "镧系",
    CAT_ACTINIDE: "锕系",
    CAT_UNKNOWN: "性质待定",
}

# ---------------------------------------------------------------- 元素结构
@dataclass(frozen=True)
class Element:
    number: int
    symbol: str
    en: str
    zh: str
    pinyin: str            # 中文生僻字的读音兜底
    mass: str              # 相对原子质量（人工元素用 [267] 表示最长寿命同位素质量数）
    category: str
    group: Optional[int]   # 族号，镧系锕系为 None
    period: int
    block: str             # s / p / d / f
    electroneg: Optional[float]
    config: str            # 电子排布
    phase: str             # 固 / 液 / 气 / 未知
    year: Optional[int]    # 发现年代（用于热力图），史前为 None
    era: str               # 发现年代的可读描述
    discoverer: str
    story: str             # 较详细的发现过程
    crust: Optional[float]   # 地壳丰度 ppm；人工元素为 None
    cosmic: Optional[float]  # 宇宙丰度（Si=10⁶）
    occurrence: str        # 在自然界的主要存在形式
    compounds: str         # 主要化合物
    uses: str              # 在生产中的用途

    # ---------------- 派生属性 ----------------
    @property
    def key(self) -> str:
        return self.symbol

    @property
    def group_label(self) -> str:
        if self.group:
            return f"第 {self.group} 族"
        return "镧系" if self.category == CAT_LANTHANIDE else "锕系"

    @property
    def category_name(self) -> str:
        return CATEGORY_NAMES[self.category]

    @property
    def crust_text(self) -> str:
        if self.crust is None:
            return "无（人工合成，地壳中不存在）"
        if self.crust >= 10000:
            return f"{self.crust / 10000:.2f} %（约 {self.crust:,.0f} ppm）"
        if self.crust >= 1:
            return f"{self.crust:,.4g} ppm"
        if self.crust >= 0.001:
            return f"{self.crust:,.4g} ppm（{self.crust * 1000:,.4g} ppb）"
        return f"{self.crust:.3g} ppm（痕量）"

    @property
    def cosmic_text(self) -> str:
        if self.cosmic is None:
            return "无（宇宙中未检出天然存在）"
        if self.cosmic >= 1e5:
            return f"{self.cosmic:.3g}（Si=10⁶）"
        if self.cosmic >= 1:
            return f"{self.cosmic:.4g}（Si=10⁶）"
        return f"{self.cosmic:.4g}（Si=10⁶，极稀少）"

    @property
    def electroneg_text(self) -> str:
        return "—" if self.electroneg is None else f"{self.electroneg:.2f}"

    def matches(self, keyword: str) -> bool:
        k = keyword.strip().lower()
        if not k:
            return True
        return (k in str(self.number) or k in self.symbol.lower()
                or k in self.en.lower() or k in self.zh
                or k in self.pinyin.lower())


def E(number, symbol, en, zh, pinyin, mass, category, group, period, block,
      electroneg, config, phase, year, era, discoverer, story,
      crust, cosmic, occurrence, compounds, uses) -> Element:
    return Element(number, symbol, en, zh, pinyin, mass, category, group, period,
                   block, electroneg, config, phase, year, era, discoverer, story,
                   crust, cosmic, occurrence, compounds, uses)


