      "中国云南个旧、马来西亚、玻利维亚、印尼为主要产地。锡在 13.2 ℃ 以下会从白锡转变为粉末状灰锡"
      "（“锡疫”），历史上拿破仑远征俄国时士兵锡纽扣粉化的传说即与此有关。",
