      "2024 年起已将锑列为出口管制战略物资。地壳中分散，海水约 0.2 ppb。",
      "Sb₂S₃（辉锑矿）、Sb₂O₃（三氧化二锑）、SbCl₃、SbCl₅、锑酸钠、酒石酸锑钾（吐酒石）、"
      "乙二醇锑、铅锑合金、GaSb、InSb、焦锑酸钠",
      "阻燃剂（三氧化二锑与溴系/氯系阻燃剂产生协效作用，用于塑料、纺织品、橡胶、电子外壳与电缆，"
      "占锑消费约 60%）；铅酸蓄电池板栅铅锑合金（提高强度、改善铸造性与深循环性能）；"
