      "他称之为 didymium（希腊语“双胞胎”），并一度被当作单一元素，甚至被门捷列夫写进周期表。"
      "1879 年布瓦博德朗先从 didymium 中分离出钐；1885 年奥地利化学家冯·韦尔斯巴赫用硝酸铵"
