      "被称为“磁王”。它使耳机、硬盘、扬声器、电动车电机与直驱风力发电机的小型化与高效化成为可能，"
      "钕也因此成为全球最关键、最受关注的战略金属之一。",
      33, 0.84,
      "伴生于氟碳铈矿（美国芒廷帕斯、中国白云鄂博）、独居石（澳大利亚韦尔德山、印度、巴西、越南）"
