      "马林斯基、格伦丁宁与科里尔在曼哈顿计划期间，从石墨反应堆辐照铀燃料的裂变产物中，"
      "用离子交换色谱首次分离出 61 号元素的放射性核素，并以希腊神话盗火者普罗米修斯 Prometheus 命名"
      "promethium —— 寓意人类从核反应中“盗取天火”。它是唯一没有稳定同位素的镧系元素。",
      None, None,
      "地壳中仅痕量存在（铀自发裂变与中子俘获的极微量产物，每千克沥青铀矿约含皮克级）；"
      "1965 年首次从沥青铀矿中检出天然钷。实用来源全部由反应堆辐照钕靶或从乏燃料后处理中分离，"
