      "磁制冷（钆及 Gd₅Si₂Ge₂ 具有巨磁热效应，是室温磁制冷样机的核心工质，有望替代压缩机制冷）；"
      "中子吸收（钆的热中子吸收截面在天然元素中最大，用于反应堆屏蔽、可燃毒物、中子照相，"
      "以及钆中子俘获治癌 GdNCT 的研究）；"
