      "NaAt、At⁻/At⁺ 离子、²¹¹At 标记生物分子（砹代化合物）、At-astatide、砹-碘类似物",
      "靶向 α 核素治疗 TAT（²¹¹At 半衰期 7.2 小时，每次衰变发射 1 个 α 粒子，"
