    E(86, "Rn", "Radon", "氡", "dōng", "[222]", CAT_NOBLE, 18, 6, "p", 2.20, "[Xe]4f¹⁴5d¹⁰6s²6p⁶", "气",
      1900, "1900 年", "弗里德里希·恩斯特·多恩（F. E. Dorn）",
      "1899 年英国物理学家欧文斯与卢瑟福注意到钍化合物会持续放出一种放射性“射气”"
      "（emanation）；1900 年德国物理学家多恩研究镭盐时发现镭也会放出类似的放射性气体，"
      "他称之为“镭射气”（radium emanation）。1908 年拉姆齐与格雷仔细测定了它的密度与光谱，"
      "确认这是一种新的稀有气体；1923 年国际化学界正式定名为 radon（源自 radium，"
      "词尾 -on 仿照氩 argon、氖 neon）。氡是唯一具有放射性的稀有气体，也是天然本底辐射的"
      "最大来源——它从土壤与建材中析出并在密闭室内累积，被世界卫生组织列为继吸烟之后"
      "导致肺癌的第二位原因。",
      None, None,
      "由镭-226（铀衰变系）与钍衰变持续产生，存在于土壤孔隙、岩石、地下水与天然气中；"
      "花岗岩地区、铀矿区与地下室、矿井中氡浓度较高；氡的子体附着于气溶胶被吸入肺部造成内照射。"
      "温泉与矿井中浓度可极高（历史上曾有“氡疗”温泉）。大气平均浓度极低（约 10⁻¹⁹ 量级）。",
      "RnF₂（二氟化氡，唯一在实验上确证的氡化合物，制备极难）、Rn 水合物与包合物（推测）",
      "地质与资源勘查（土壤氡气测量用于寻找隐伏铀矿、地热资源、隐伏断裂与地下水通道）；"
      "地震与断层监测（断层带氡浓度异常被视为地震前兆研究的重要手段之一）；"
      "建筑与室内环境（氡浓度检测是住宅、学校与地下空间验收的重要项目；"
      "防氡设计与通风是肺癌预防的重要公共卫生措施）；"
      "水文与海洋学（氡示踪地下水补给、地下水—地表水交互与海底地下水排泄）；"
      "辐射防护与剂量学研究（氡及其子体是公众天然本底辐射剂量的最大贡献者，约占一半）；"
      "医学（历史上用于“氡泉浴疗”与近距离放疗的氡籽源，现已淘汰）。"
      "健康提示：氡是世界卫生组织确认的Ⅰ类致癌物，室内氡浓度宜控制在 100~300 Bq/m³ 以下。"),

