      "1829 年他在挪威布雷维克（Brevik）附近勒弗岛的另一块矿石中再次分离出同一种“土”，"
      "这一次证据确凿，钍的发现由此确立，该矿物后来也被命名为硅酸钍矿（thorite）。"
      "1898 年居里夫妇发现钍同样具有放射性。1930 年代起，钍因 ²³²Th 吸收中子后可转化为"
