      "（1965—1969 年）。近年钍基熔盐堆在中国、印度与挪威重新成为第四代核能的重要方向。",
      9.6, 0.0335,
      "地壳中钍的丰度约为铀的 3~4 倍（约 9.6 ppm），主要矿物为独居石"
      "（monazite，(Ce,La,Nd,Th)PO₄，是稀土矿的重要伴生矿）与钍石 ThSiO₄；"
      "印度（喀拉拉邦海滩砂）、巴西、澳大利亚、美国、中国（白云鄂博尾矿）为主要来源。"
      "钍几乎总是与稀土共生，既是稀土开采的伴生资源，也是需要处理的放射性副产物。",
      "ThO₂（二氧化钍，熔点最高的氧化物之一）、Th(NO₃)₄、ThF₄、ThCl₄、"
      "硝酸钍（白炽气灯纱罩）、Th-U 混合氧化物、钍钨电极",
      "核燃料（²³²Th 吸收中子后转化为可裂变的 ²³³U，可用于钍基熔盐堆 TMSR、高温气冷堆与"
      "重水堆，具有资源丰富、固有安全性高、核废料少与防核扩散的优点；"
      "中国甘肃武威的 2 MWt 液态燃料钍基熔盐实验堆已于 2023 年获运行许可，"
      "是全球钍能开发的标志性进展）；"
      "焊接电极（钍钨电极 TIG 起弧稳定、寿命长、载流能力强，仍广泛使用，"
