      None, None,
      "地壳中极微量存在（²³¹Pa 与铀矿中的铀处于放射性平衡，含量约为铀的千万分之一量级），"
      "也存在于深海锰结核与海洋沉积物中。实用来源主要从铀矿加工副产物、"
