# ---------------------------------------------------------------- 生僻字回退
#: 104~118 号元素的规范汉字多为 CJK 扩展区字符，常见字体（如微软雅黑）未必包含。
#: 当字体缺字时，用“钅+声旁”的通用写法代替，避免出现方框（豆腐块）。
ZH_FALLBACK = {
    104: "钅卢", 105: "钅杜", 106: "钅喜", 107: "钅波", 108: "钅黑",
    109: "钅麦", 110: "钅达", 111: "钅仑", 112: "钅哥", 113: "钅尔",
    114: "钅夫", 115: "镆", 116: "钅立", 117: "钅田", 118: "钅奥",
}


#: 微软雅黑等常见字体只覆盖 U+4E00~U+9FA5 的基本汉字区，
#: 超出该范围的扩展区字符一律视为缺字（否则会显示成方框）。
BASIC_CJK_MAX = 0x9FA5


def is_zh_glyph_known(ch: str) -> bool:
    return ord(ch) <= BASIC_CJK_MAX


def zh_display(e: Element, glyph_ok=None) -> str:
    """返回可显示的中文名；缺字时用“钅+声旁”的通用写法。

    glyph_ok(ch)->bool 可由调用方传入更精确的字体缺字判断（如查字体 cmap）。
    """
    if glyph_ok is not None:
        known = all(glyph_ok(ch) for ch in e.zh)
    else:
        known = all(is_zh_glyph_known(ch) for ch in e.zh)
    return e.zh if known else ZH_FALLBACK.get(e.number, e.zh)


# ==================================================================== 索引与查询
ELEMENTS: List[Element] = RAW
BY_NUMBER = {e.number: e for e in ELEMENTS}
BY_SYMBOL = {e.symbol: e for e in ELEMENTS}

# 主表布局：行=周期(1~7)，列=族(1~18)；镧系/锕系单独列出
LANTHANIDES: List[Element] = [e for e in ELEMENTS if e.category == CAT_LANTHANIDE]
ACTINIDES: List[Element] = [e for e in ELEMENTS if e.category == CAT_ACTINIDE]

MAIN_TABLE: List[Element] = [
    e for e in ELEMENTS
    if e.category not in (CAT_LANTHANIDE, CAT_ACTINIDE) and e.group is not None
]

#: 用于在主表第 6、7 周期放置占位格（指向镧系/锕系序列）
F_BLOCK_PLACEHOLDER = {
    6: LANTHANIDES,   # 第 6 周期第 3 列放镧系占位
    7: ACTINIDES,     # 第 7 周期第 3 列放锕系占位
}


def element_at(period: int, group: int) -> Optional[Element]:
    """按周期与族号取元素（镧系/锕系位置返回 None）。"""
    for e in ELEMENTS:
        if e.period == period and e.group == group and \
                e.category not in (CAT_LANTHANIDE, CAT_ACTINIDE):
            return e
    return None


def search(keyword: str) -> List[Element]:
    return [e for e in ELEMENTS if e.matches(keyword)]


def all_years() -> List[int]:
    return sorted({e.year for e in ELEMENTS if e.year is not None})


def validate() -> List[str]:
    """自检：序号连续、符号唯一、族周期合法。"""
    problems = []
    if len(ELEMENTS) != 118:
        problems.append(f"元素数量应为 118，实际 {len(ELEMENTS)}")
    for idx, e in enumerate(ELEMENTS, start=1):
        if e.number != idx:
            problems.append(f"序号错位：第 {idx} 项为 {e.number}")
    if len(BY_SYMBOL) != len(ELEMENTS):
        problems.append("存在重复元素符号")
    for e in ELEMENTS:
        if not (1 <= e.period <= 7):
            problems.append(f"{e.symbol} 周期非法：{e.period}")
        if e.group is not None and not (1 <= e.group <= 18):
            problems.append(f"{e.symbol} 族号非法：{e.group}")
    return problems


if __name__ == "__main__":
    errs = validate()
    print("元素总数：", len(ELEMENTS))
    print("镧系：", len(LANTHANIDES), " 锕系：", len(ACTINIDES))
    print("自检结果：", "全部通过" if not errs else errs)

